bool parse_count(const char *text, size_t *out) {
    if (text == NULL || out == NULL || *text == '\0') return false;
    char *end = NULL;
    errno = 0;
    unsigned long value = strtoul(text, &end, 10);
    if (errno != 0 || end == text || *end != '\0') return false;
    if (value > MAX_ITEMS) return false;
    *out = (size_t)value;
    return true;
}

