int copy_text(char *dst, size_t capacity, const char *src) {
    if (!dst || !src || capacity == 0) return -1;
    size_t n = strlen(src);
    if (n >= capacity) return -2;
    memcpy(dst, src, n + 1);
    return 0;
}

int load_data(const char *path) {
    int status = -1;
    FILE *fp = NULL;
    char *buffer = NULL;

    fp = fopen(path, "rb");
    if (!fp) goto cleanup;
    buffer = malloc(BUFFER_SIZE);
    if (!buffer) goto cleanup;
    /* validate and process */
    status = 0;
cleanup:
    free(buffer);
    if (fp) fclose(fp);
    return status;
}
